  Future<void> _loadListings() async {
    try {
      final List<StayListing> found =
          await StayListingService.instance.mostPartnersNearby(limit: 12);
      if (!mounted) return;
      setState(() {
        _listings = found;
        _error = null;
        _loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      // Falls back to the empty state rather than an error page. Search still
      // works, so a guest is not stuck — and the empty state says what to do.
      setState(() {
        _listings = const <StayListing>[];
        _error = e.toString();
        _loading = false;
      });
    }
